var tokens = (Console.ReadLine() ?? "").Trim().Split(' ', StringSplitOptions.RemoveEmptyEntries);
if (tokens.Length < 1 || tokens.Length > 50) Environment.Exit(1);
var values = new int[tokens.Length];
for (var index = 0; index < tokens.Length; index++)
{
    if (!int.TryParse(tokens[index], out var value) || value < -1000000 || value > 1000000) Environment.Exit(1);
    values[index] = value;
}
var partialSums = new long[2];
var evenCounts = new int[2];
var workers = new Thread[2];
for (var workerIndex = 0; workerIndex < workers.Length; workerIndex++)
{
    var slot = workerIndex;
    workers[slot] = new Thread(() =>
    {
        long sum = 0;
        var even = 0;
        for (var index = slot; index < values.Length; index += 2)
        {
            sum += values[index];
            if (values[index] % 2 == 0) even++;
        }
        partialSums[slot] = sum;
        evenCounts[slot] = even;
    });
}
foreach (var worker in workers) worker.Start();
foreach (var worker in workers) worker.Join();
Console.WriteLine($"sum={partialSums[0] + partialSums[1]} even={evenCounts[0] + evenCounts[1]}");
